sp_widget.client_script:
api.controller = function($scope, $timeout) {
    var c = this;
    var STORAGE_KEY = "dm_failure_config";
    var isSaving = false;


    c.email = '';
    c.emailError = '';


    function showToast(message, type) {
        document.dispatchEvent(new CustomEvent("dm.showToast", {
            detail: {
                message: message,
                type: type
            }
        }));
    }


    function isValidEmail(email) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    }


    function validate() {
        if (!c.email)
            c.emailError = "Please enter an email";
        else if (!isValidEmail(c.email))
            c.emailError = "Invalid email format";
        else
            c.emailError = '';
    }


    function fetchEmailFromServer() {


        if (!c.group || !c.group.value) return;


        c.server.get({
            action: 'getGroupEmail',
            group_id: c.group.value
        }).then(function(res) {
            c.email = res.data.email || '';
            validate();
        });
    }


    function loadState() {
        var saved = sessionStorage.getItem(STORAGE_KEY);


        if (saved) {
            try {
                var data = JSON.parse(saved);
                c.email = data.email || '';
                c.group = data.group || null;
                validate();
                return true; // saved state found
            } catch (e) {}
        }
        return false; // no saved state
    }


    function loadDefaults() {
        c.server.get({
            action: 'loadDefaults'
        }).then(function(res) {
            if (res.data.defaultGroup) {
                c.group = res.data.defaultGroup;
                c.email = res.data.defaultEmail || '';
                validate();
            }
        });
    }


    function saveState() {
        sessionStorage.setItem(STORAGE_KEY, JSON.stringify({
            email: c.email,
            group: c.group
        }));
    }


    $scope.$on('setup.reset', function() {
        sessionStorage.removeItem(STORAGE_KEY);
        c.group = null;
        c.email = '';
    });


    c.$onInit = function() {
        var hasSavedState = loadState();
        if (!hasSavedState) {
            loadDefaults();
        }
    };


    c.onGroupChange = function() {
        fetchEmailFromServer();
    };


    window.addEventListener('focus', function() {


        if (isSaving) return;


        if (c.group && c.group.value) {
            $timeout(function() {
                fetchEmailFromServer();
            });
        }
    });


    c.openGroupRecord = function() {


        if (!c.group || !c.group.value) return;


        var url = window.location.origin +
            '/nav_to.do?uri=sys_user_group.do?sys_id=' + c.group.value;
        window.location.href = url;


    };


    c.saveFailureConfig = function() {
        if (!c.group || !c.group.value) return;


        isSaving = true;
        c.showSuccess = false;


        c.server.get({
            action: 'saveFailureConfig',
            group_id: c.group.value,
            email: c.email
        }).then(function() {


            saveState();


            c.showSuccess = true;
            isSaving = false;


            $timeout(function() {
                c.showSuccess = false;
            }, 5000);
        });
    };


};

sp_widget.css:
.section {
  display: none;
}

.am-card {
    position: relative;
    background: #ffffff;
    border: 2px solid #e5e7eb !important;
    border-radius: 10px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.05);
    margin-bottom: 20px;
}

.am-card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 14px;
    font-size: 16px;
    font-weight: 600;
    color: #111827;
    background: #f9fafb;
    border-bottom: 1px solid #e5e7eb;
}

.am-header-text {
    flex: 1;
}

.am-header-actions {
    display: flex;
    gap: 8px;
    margin-left: 16px;
}

.am-card-body {
    padding: 20px;
}

.am-subtitle {
    color: #64748b;
    font-size: 13px;
    margin: 0 0 16px 0;
}

.am-field label {
    display: block;
    font-size: 13px;
    color: #6b7280;
    margin-bottom: 6px;
}

.form-control[readonly] {
    background: #f3f4f6;
    cursor: not-allowed;
    color: #4b5563;
}

.am-link-btn {
    padding-left: 0;
    margin-top: 6px;
    font-size: 12px;
}

.am-toast {
    position: absolute;
    top: 15px;
    left: 50%;
    transform: translateX(-50%);
    z-index: 9999;

    background: #E7F6EC;
  	border: 1px solid #9FE0B5;
    color: #006B50;
    border-radius: 4px;
    padding: 10px 20px;
    font-weight: 600;
    box-shadow: 0 3px 8px rgba(0,0,0,0.2);
}

sp_widget.script:
(function () {
var action = input && input.action;


if (action == 'getGroupEmail') {


var grp = new GlideRecordSecure('sys_user_group');


if (input.group_id && grp.get(input.group_id)) {
            data.email = grp.getValue('email') || '';
        } else {
            data.email = '';
        }
    }


if (action == 'saveFailureConfig') {
        gs.setProperty('x_hpws_wrkfrcexpam.notify_failure_group', input.email);
    }


if (action == 'loadDefaults') {
        data.defaultGroup = null;
        data.defaultEmail = '';


var savedEmail = gs.getProperty('x_hpws_wrkfrcexpam.notify_failure_group', '');


if (savedEmail) {
            var grp = new GlideRecordSecure('sys_user_group');
            grp.addQuery('email', savedEmail);
            grp.setLimit(1);
            grp.query();


if (grp.next()) {
                data.defaultGroup = {
                    value: grp.getUniqueValue(),
                    displayValue: grp.getDisplayValue('name')
                };
                data.defaultEmail = savedEmail;
            }
        }
    }


})();
